import java.util.Map;

public class ClassX {
    /**
     * Valida el encabezado del token para asegurar que el algoritmo es compatible.
     * 
     * La función verifica si el campo 'alg' en el encabezado contiene 'HS256'.
     */
    public boolean isValidAlg(String header) {
        // Dividimos el header en campos
        String[] parts = header.split(",");

        // Buscamos el campo 'alg'
        for (String part : parts) {
            if (part.trim().equals("alg=HS256")) {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        ClassX example = new ClassX();

        // Ejemplos de encabezados de tokens para probar la función isValidAlg
        String tokenHeader1 = "alg=HS256,typ=JWT";
        String tokenHeader2 = "alg=RS256,typ=JWT";

        System.out.println(example.isValidAlg(tokenHeader1)); // Debería imprimir true
        System.out.println(example.isValidAlg(tokenHeader2)); // Debería imprimir false
    }
}
```

