import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {
    private static final Pattern INVALID_HOST_PATTERN = Pattern.compile("[^a-zA-Z0-9.-]");

    /**
     * Fetches content from a generated URL after validating the host.
     * 
     * This function sanitizes the host by checking for invalid characters like spaces.
     * 
     * @param url The URL to fetch content from.
     * @return The content of the URL as a string.
     * @throws Exception If there is an error fetching the URL or the host is invalid.
     */
    public static String fetchContent(String url) throws Exception {
        URL validatedUrl = validateHost(new URL(url));
        HttpURLConnection connection = (HttpURLConnection) validatedUrl.openConnection();
        connection.setRequestMethod("GET");
        int responseCode = connection.getResponseCode();

        if (responseCode == HttpURLConnection.HTTP_OK) {
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();
            return content.toString();
        } else {
            throw new Exception("Failed to fetch content. HTTP status code: " + responseCode);
        }
    }

    /**
     * Validates the host of the given URL.
     * 
     * Invalid hosts are those containing spaces, which are prohibited by the URL specification.
     * 
     * @param url The URL to validate.
     * @return The validated URL with a sanitized host.
     * @throws IllegalArgumentException If the host contains invalid characters.
     */
    private static URL validateHost(URL url) {
        String host = url.getHost();
        if (INVALID_HOST_PATTERN.matcher(host).find()) {
            throw new IllegalArgumentException("Invalid URL: Host contains invalid characters.");
        }
        return new URL(url.getProtocol(), url.getUserInfo(), host, url.getPort(), url.getPath(), url.getQuery(), url.getRef());
    }
}
