public class ClassX {
    /**
     * Mengambil konten dari URL yang dihasilkan setelah memvalidasi host.
     * 
     * Fungsi ini membersihkan host dengan memeriksa karakter tidak valid seperti spasi.
     * @param urlString URL yang akan dimasukkan dalam bentuk string.
     * @return Konten dari URL yang valid.
     * @throws MalformedURLException Jika terjadi kesalahan saat membuat URL.
     */
    public String getContentFromValidatedHost(String urlString) throws MalformedURLException {
        // Coba membuat URL dari string yang diberikan
        URL url = new URL(urlString);

        // GetHostname method mengembalikan hostname yang mungkin memiliki karakter tidak valid
        String originalHost = url.getHost();

        // Membersihkan hostname
        String sanitizedHost = originalHost.replace(" ", "");

        // Set hostname kembali pada URL
        url = new URL(url.getProtocol(), sanitizedHost, url.getPort(), url.getFile());

        // Membuat connection ke URL
        java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        // Mendapatkan status code
        int responseCode = connection.getResponseCode();

        // Jika kode respon tidak berhasil, throw exception
        if (responseCode != 200) {
            throw new MalformedURLException("Failed to retrieve content: " + connection.getResponseMessage());
        }

        // Membaca konten dari respons
        java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String inputLine;

        while ((inputLine = in.readLine()) != null) {
            content.append(inputLine).append("\n");
        }
        in.close();

        // Menutup koneksi
        connection.disconnect();

        // Mereturn konten dari URL yang valid
        return content.toString();
    }
}
