        // Remove empty spaces from the host part of the URL
        int index = urlString.indexOf("//");
        if (index != -1) {
            index += 2; // Skip "//"
            String host = urlString.substring(index);
            StringBuilder cleanedHost = new StringBuilder();
            for (char c : host.toCharArray()) {
                if (c != ' ') {
                    cleanedHost.append(c);
                }
            }
            return urlString.replace(host, cleanedHost.toString());
        }
        return urlString; // URL does not contain a host part
    }
}
