import java.net.URL;

public class ClassX {
    public static String getURLContent(String urlString) {
        try {
            // Parse the URL
            URL url = new URL(urlString);
            // Validate the host
            String host = url.getHost();
            if (host.contains(" ")) {
                throw new IllegalArgumentException("Invalid host: spaces are not allowed.");
            }
            // Create a URL object again with cleaned host
            URL cleanUrl = new URL(url.getProtocol(), host.replaceAll("\\s", ""), url.getPort(), url.getFile());
            // Open a connection to the URL
            java.net.HttpURLConnection con = (java.net.HttpURLConnection) cleanUrl.openConnection();
            con.setRequestMethod("GET");
            con.connect();
            int responseCode = con.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                // Read the content
                java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(con.getInputStream()));
                StringBuilder content = new StringBuilder();
                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    content.append(inputLine);
                }
                in.close();
                return content.toString();
            } else {
                throw new RuntimeException("Failed to retrieve content. HTTP response code: " + responseCode);
            }
        } catch (Exception e) {
            throw new RuntimeException(e.getMessage());
        }
    }

    public static void main(String[] args) {
        String urlString = "http://example.com";
        String content = getURLContent(urlString);
        System.out.println(content);
    }
}
