     * @param urlStr URL cần truy cập
     * @return Nội dung từ URL sau khi đã làm sạch
     * @throws IOException Nếu xảy ra lỗi khi truy cập URL
     */
    public String fetchAndSanitizeContent(String urlStr) throws IOException {
        // Kiểm tra URL hợp lệ
        if (urlStr == null || !urlStr.startsWith("http://") && !urlStr.startsWith("https://")) {
            throw new IllegalArgumentException("URL không hợp lệ");
        }

        URL url = new URL(urlStr);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        // Xác thực máy chủ
        connection.connect();

        // Kiểm tra trạng thái kết nối
        int responseCode = connection.getResponseCode();
        if (responseCode != HttpURLConnection.HTTP_OK) {
            throw new RuntimeException("Máy chủ trả về mã HTTP không thành công: " + responseCode);
