import java.util.regex.Matcher;

public class ClassX {
    private static final Pattern URL_REGEX = Pattern.compile(
        "^https?:\\/\\/([a-zA-Z0-9.-]+)(\\/[a-zA-Z0-9.-]*)*$"
    );

    /**
     * Haal inhoud van 'n gegenereerde URL af nadat die gasheer geverifieer is.
     * 
     * Deze funksie sanitiseer die gasheer deur te kyk vir ongeldige karakters soos spaties en controleer of die gasheer een handige URL is.
     */
    public String fetchUrlContent(String url) {
        // Sanitiseer die URL
        Matcher matcher = URL_REGEX.matcher(url);
        if (!matcher.matches()) {
            throw new IllegalArgumentException("Ongeldige URL");
        }

        try {
            URL website = new URL(url);
            BufferedReader in = new BufferedReader(new InputStreamReader(website.openStream()));
            StringBuilder response = new StringBuilder();

            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();

            return response.toString();
        } catch (Exception e) {
            throw new RuntimeException("Kon URL nie verwerken: " + url, e);
        }
    }
}
