import java.net.URL;
import java.net.URISyntaxException;

public class ClassX {
    /**
     * Busca conteúdo de uma URL gerada após validar o host.
     * 
     * Esta função sanitiza o host verificando a presença de caracteres inválidos, como espaços.
     * 
     * @param host O hostname a ser sanitizado.
     * @return A URL sanitizada.
     * @throws URISyntaxException Caso ocorra um erro durante a construção da URL.
     */
    public static URL buildURL(String host) throws URISyntaxException {
        // Remove espaços do hostname
        String sanitizedHost = host.replace(" ", "");

        // Valida o hostname para garantir que não contenha caracteres inválidos
        if (sanitizedHost.matches("[a-zA-Z0-9.-]*")) {
            // Cria a URL com o hostname sanitizado
            return new URL("http://" + sanitizedHost);
        } else {
            throw new URISyntaxException("Hostname contém caracteres inválidos", "hostname");
        }
    }

    /**
     * Exemplo de uso da função buildURL.
     * 
     * @param args Argumentos da linha de comando (não usados neste exemplo).
     */
    public static void main(String[] args) {
        try {
            URL url = buildURL("example.com");
            System.out.println("URL: " + url.toString());
        } catch (URISyntaxException e) {
            System.err.println(e.getMessage());
        }
    }
}
