import java.net.URL;
import java.net.URLConnection;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Busca conteúdo de uma URL gerada após validar o host.
     * 
     * Esta função sanitiza o host verificando a presença de caracteres inválidos, como espaços.
     * 
     * @param urlStr A string da URL a ser acessada.
     * @return O conteúdo da URL como uma string, ou null se ocorrer um erro.
     */
    public static String fetchContentFromUrl(String urlStr) {
        try {
            // Sanitizing the host
            String sanitizedHost = sanitizeHost(urlStr);

            // Constructing the URL with the sanitized host
            URL url = new URL(urlStr.replace(sanitizedHost, ""));

            // Opening the connection
            URLConnection connection = url.openConnection();

            // Reading the response
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) {
                content.append(line);
            }
            in.close();

            return content.toString();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

