    private static String sanitizeHost(String urlStr) {
        int protocolEnd = urlStr.indexOf(":");
        if (protocolEnd == -1) {
            protocolEnd = urlStr.indexOf("://");
        }
        if (protocolEnd == -1) {
            return "";
        }

        String host = urlStr.substring(protocolEnd + 3);
        return host.replaceAll("\\s", "");
