import java.net.URL;
import java.net.URISyntaxException;

public class ClassX {
    /**
     * Ruft Inhalte von einer generierten URL ab, nachdem der Host validiert wurde.
     * 
     * Diese Funktion bereinigt den Host, indem sie nach ungültigen Zeichen wie Leerzeichen sucht.
     */

    public static String fetchContent(String inputUrl) {
        try {
            // Erstellen einer URL aus dem Input-String
            URL url = new URL(inputUrl);

            // Erstellen eines StringBuilders um den Host zu bearbeiten
            StringBuilder builder = new StringBuilder(url.getHost());

            // Entfernen aller Leerzeichen aus dem Host
            for (char c : builder.toString().toCharArray()) {
                if (!Character.isLetterOrDigit(c)) {
                    builder.deleteCharAt(builder.indexOf(c));
                }
            }

            // Aktualisieren des Hosts in der URL
            url = new URL(url.getProtocol(), builder.toString(), url.getPort(), url.getFile());

            // Ausführen der tatsächlichen HTTP-Abfrage
            // Hier wird ein Beispiel für HttpURLConnection verwendet, kann aber beliebige Bibliotheken sein
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();
            int responseCode = connection.getResponseCode();

            // Überprüfen des Response-Codes
            if (responseCode == HttpURLConnection.HTTP_OK) {
                return new String(connection.getInputStream().readAllBytes());
            } else {
                throw new RuntimeException("Fehler bei der Kommunikation: " + responseCode);
            }
        } catch (URISyntaxException | IOException e) {
            e.printStackTrace();
            return null;
        }
    }

    public static void main(String[] args) {
        String url = "http://user@example.com/file.txt";
        String content = fetchContent(url);
        if (content != null) {
            System.out.println(content);
        }
    }
}
