import java.net.URL;
import java.net.URLEncoder;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Ruft Inhalte von einer generierten URL ab, nachdem der Host validiert wurde.
     * 
     * Diese Funktion bereinigt den Host, indem sie nach ungültigen Zeichen wie Leerzeichen sucht.
     * 
     * @param hostname Der Hostnamen der URL
     * @return Die gültige URL
     * @throws IllegalArgumentException Wenn der Hostname ungültig ist
     */
    public static URL getValidURL(String hostname) throws IllegalArgumentException {
        // Definiere eine reguläre Expression um ungültige Zeichen in einem Hostnamen zu finden
        Pattern pattern = Pattern.compile("[^a-zA-Z0-9-]");
        Matcher matcher = pattern.matcher(hostname);

        // Überprüfe, ob der Hostname ungültige Zeichen enthält
        if (matcher.find()) {
            throw new IllegalArgumentException("Ungültiges Zeichen im Hostnamen: " + matcher.group());
        }

        try {
            // Erstelle eine gültige URL mit dem bereinigten Hostnamen
            return new URL("https://" + URLEncoder.encode(hostname, "UTF-8") + "/");
        } catch (Exception e) {
            throw new IllegalArgumentException("Fehler beim Erstellen der URL: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        try {
            // Beispielaufruf
            URL url = getValidURL("example.com");
            System.out.println("Gültige URL: " + url.toString());
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
}
```

