import java.net.URL;
import java.net.URISyntaxException;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Recupera contenuti da un URL generato dopo aver convalidato l'host.
     * 
     * Questa funzione sanifica l'host controllando la presenza di caratteri non validi come gli spazi.
     * 
     * @param hostHost Host del server per cui recuperare i contenuti. Può contenere spazi.
     * @return URL sanitizzato utilizzando lo spazio come separatore tra dominio e porta se necessario.
     */
    public static URL validateAndSanitizeHost(String host) throws URISyntaxException, IllegalArgumentException {
        // Definiamo un pattern per validare l'host
        Pattern pattern = Pattern.compile("^(([^:\\s]+)(\\:([0-9]+))?)$");
        Matcher matcher = pattern.matcher(host);

        if (!matcher.matches()) {
            throw new IllegalArgumentException("Host non valido: " + host);
        }

        String domain = matcher.group(1);
        int port = matcher.group(4) != null ? Integer.parseInt(matcher.group(4)) : 80; // Porta predefinita

        // Sanitizziamo l'host in caso di spazi
        String sanitizedHost = domain.replaceAll("\\s", "%20");

        // Creiamo l'URL utilizzando la sanitizzazione dell'host
        return new URL(sanitizedHost, port);
    }
}
```

