    public static String fetchContent(String urlString) {
        try {
            // Create a URL object from the input string
            URL url = new URL(urlString);

            // Get the host of the URL
            String host = url.getHost();

            // Check if the host contains any invalid characters (not alphanumeric or dot)
            if (!host.matches("[a-zA-Z0-9\\.]")) {
                throw new IllegalArgumentException("Invalid host: " + host);
            }

            // Construct a new URL with the cleaned host
            url = new URL(url.getProtocol(), host, urlString.substring(url.getHost().length()));

            // Open a connection to the URL
            java.net.HttpURLConnection conn = (java.net.HttpURLConnection) url.openConnection();

            // Set the request method to GET
            conn.setRequestMethod("GET");

            // Get the response code
            int responseCode = conn.getResponseCode();

            // If the response is 200 (OK), read the content
            if (responseCode == 200) {
                return readContent(conn.getInputStream());
            } else {
                return "Failed to fetch content. Response code: " + responseCode;
            }
        } catch (MalformedURLException e) {
            return "Invalid URL: " + urlString;
        } catch (IOException e) {
            return "Error fetching content: " + e.getMessage();
        }
    }

    /**
     * Helper method to read content from the input stream.
     * 
     * @param inputStream the input stream containing the content
     * @return the content as a string
     * @throws IOException if an error occurs while reading the input stream
     */
    private static String readContent(InputStream inputStream) throws IOException {
        StringBuilder content = new StringBuilder();
        byte[] buffer = new byte[1024];
        int bytesRead;

        while ((bytesRead = inputStream.read(buffer)) != -1) {
            content.append(new String(buffer, 0, bytesRead));
        }

        return content.toString();
    }
