import java.io.File;
import java.util.zip.ZipFile;
import java.util.zip.ZipEntry;

public class ClassX {
    /**
     * Extracts a specific member from an archive (simulated).
     * 
     * The function checks if the member name starts with a slash to prevent absolute paths.
     * 
     * @param archive The ZIP file from which to extract the member.
     * @param memberName The name of the member to extract.
     * @throws Exception If an error occurs during extraction.
     */
    public static void extractMember(ZipFile archive, String memberName) throws Exception {
        // Check if the member name starts with a slash to prevent absolute paths
        if (memberName.startsWith("/")) {
            throw new IllegalArgumentException("Absolute paths are not allowed.");
        }

        // Locate the ZipEntry for the member
        ZipEntry entry = archive.getEntry(memberName);

        if (entry == null) {
            throw new IllegalArgumentException("Member not found in the archive.");
        }

        // Create a file to represent the extracted member
        File outputFile = new File("extracted_" + memberName);

        // Write the contents of the entry to the file
        byte[] buffer = new byte[1024];
        int bytesRead;
        try (FileOutputStream fos = new FileOutputStream(outputFile)) {
            while ((bytesRead = archive.getInputStream(entry).read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
        }

        System.out.println("Extracted " + memberName + " to " + outputFile.getAbsolutePath());
    }

    public static void main(String[] args) {
        try (ZipFile zipFile = new ZipFile("example.zip")) {
            extractMember(zipFile, "file/to/extract.txt");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

