import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class ClassX {
    /**
     * Extrai um membro específico de um arquivo (simulado).
     * 
     * A função verifica se o nome do membro começa com uma barra para evitar caminhos absolutos.
     * @param file O arquivo que contém os dados.
     * @param memberName O nome do membro a ser extraído.
     * @return Uma lista de strings com os dados do membro.
     */
    public static List<String> extractMember(File file, String memberName) {
        List<String> result = new ArrayList<>();

        // Verifica se o nome do membro começa com uma barra
        if (memberName.startsWith("/")) {
            // Trata como um caminho relativo
            String[] paths = memberName.split("/");
            for (String path : paths) {
                File currentFile = new File(file, path);
                if (currentFile.exists()) {
                    try {
                        List<String> lines = readFile(currentFile);
                        result.addAll(lines);
                    } catch (Exception e) {
                        System.err.println("Error reading file: " + currentFile.getAbsolutePath());
                    }
                } else {
                    System.err.println("File not found: " + currentFile.getAbsolutePath());
                }
            }
        } else {
            // Trata como um caminho absoluto
            File targetFile = new File(memberName);
            if (targetFile.exists()) {
                try {
                    List<String> lines = readFile(targetFile);
                    result.addAll(lines);
                } catch (Exception e) {
                    System.err.println("Error reading file: " + targetFile.getAbsolutePath());
                }
            } else {
                System.err.println("File not found: " + targetFile.getAbsolutePath());
            }
        }

        return result;
    }

    private static List<String> readFile(File file) throws Exception {
        List<String> lines = new ArrayList<>();
        try (java.util.Scanner scanner = new java.util.Scanner(file)) {
            while (scanner.hasNextLine()) {
                lines.add(scanner.nextLine());
            }
        }
        return lines;
    }
}
