public class ClassX {
    public static void extractMemberFromArchive(String archivePath, String memberName) throws IOException {
        // Prüfen, ob der Mitgliedsname mit einem Schrägstrich beginnt
        if (memberName.startsWith("/")) {
            System.out.println("Der Mitgliedsname beginnt mit einem Schrägstrich und wird daher als absoluter Pfad interpretiert.");
            return;
        }

        // Erstellen Sie ein File-Objekt für den Archive-Pfad
        File archive = new File(archivePath);
        if (!archive.exists()) {
            System.out.println("Das Archiv existiert nicht.");
            return;
