public class Extractor {
    public static void main(String[] args) {
        if (args.length != 2) {
            System.out.println("Usage: java Extractor <archive.zip> <memberName>");
            return;
        }

        String zipFileName = args[0];
        String memberName = args[1];

        File file = new File(zipFileName);
        if (!file.exists() || !file.isFile()) {
            System.out.println("Error: The specified file does not exist or is not a file.");
            return;
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(file))) {
            ZipEntry entry = zis.getNextEntry();
            while (entry != null) {
                String entryName = entry.getName();
                if (entryName.startsWith("/")) {
                    entryName = entryName.substring(1); // Remove the leading slash
                }
                if (entryName.equals(memberName)) {
                    System.out.println("Extracting: " + entryName);
                    extractEntry(zis, entryName);
                    break;
                }
                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        } catch (Exception e) {
            System.err.println("Error extracting file: " + e.getMessage());
        }
    }

    private static void extractEntry(ZipInputStream zis, String entryName) throws Exception {
        File outputFile = new File(entryName);
        if (!outputFile.getParentFile().exists()) {
            outputFile.getParentFile().mkdirs();
        }

        try (FileOutputStream fos = new FileOutputStream(outputFile)) {
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = zis.read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
        }
    }
}
