import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class ClassX {
    /**
     * Estrae un membro specifico da un archivio (simulato).
     * 
     * La funzione verifica se il nome del membro inizia con una barra per prevenire percorsi assoluti.
     * 
     * @param zipFilePath Path al file del file ZIP simulato.
     * @param memberName Nome del membro all'interno dell'archivio.
     * @return Il contenuto del membro come una stringa, o null se l'operazione fallisce.
     */
    public static String extractMember(String zipFilePath, String memberName) {
        try (ZipFile zipFile = new ZipFile(zipFilePath)) {
            ZipEntry entry = zipFile.getEntry(memberName);

            if (entry != null && !memberName.startsWith("/")) {
                try (InputStream inputStream = zipFile.getInputStream(entry)) {
                    StringBuilder contentBuilder = new StringBuilder();
                    byte[] buffer = new byte[1024];
                    int bytesRead;

                    while ((bytesRead = inputStream.read(buffer)) != -1) {
                        contentBuilder.append(new String(buffer, 0, bytesRead));
                    }

                    return contentBuilder.toString();
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            } else {
                System.out.println("Il nome del membro deve iniziare con una barra.");
                return null;
            }
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }

    public static void main(String[] args) {
        // Example usage
        String zipFilePath = "path/to/your/zipfile.zip";
        String memberName = "folder/file.txt";
        String content = extractMember(zipFilePath, memberName);

        if (content != null) {
            System.out.println("Contenuto del membro:\n" + content);
        }
    }
}
