     */
    public void extractMember(String archivePath, String memberName) throws Exception {
        File archive = new File(archivePath);
        if (!archive.exists()) {
            throw new FileNotFoundException("Arşiv bulunamadı");
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(archive))) {
            ZipEntry entry = zis.getNextEntry();
            while (entry != null) {
                if ((entry.isDirectory() && memberName.startsWith("/") && entry.getName().startsWith(memberName)) ||
                    (!entry.isDirectory() && memberName.equals(entry.getName()))) {
                    File targetFile = new File(entry.getName());
                    if (!targetFile.getParentFile().exists()) {
                        targetFile.getParentFile().mkdirs();
                    }

                    FileOutputStream fos = new FileOutputStream(targetFile);
                    byte[] buffer = new byte[1024];
                    int len;
                    while ((len = zis.read(buffer)) > 0) {
                        fos.write(buffer, 0, len);
                    }
                    fos.close();
                }
                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        }
    }
}
