import java.util.zip.ZipInputStream;
import java.util.zip.ZipOutputStream;

public class ArchiveUtils {

    public static void extractMember(File archiveFile, File destination, String memberName) throws Exception {
        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(archiveFile))) {
            ZipEntry entry = zipIn.getNextEntry();
            while (entry != null) {
                if (entry.getName().equals(memberName)) {
                    File destFile = new File(destination, entry.getName());
                    extractEntry(zipIn, destFile);
                    break;
                }
                zipIn.closeEntry();
                entry = zipIn.getNextEntry();
            }
        }
    }

    private static void extractEntry(ZipInputStream zipIn, File destFile) throws IOException {
        File parentDir = destFile.getParentFile();
        if (!parentDir.exists()) {
            parentDir.mkdirs();
        }
        try (FileOutputStream fos = new FileOutputStream(destFile)) {
            byte[] buffer = new byte[1024];
            int len;
            while ((len = zipIn.read(buffer)) > 0) {
                fos.write(buffer, 0, len);
            }
        }
    }

    public static void main(String[] args) {
        // Example usage
        File archiveFile = new File("example.zip");
        File destination = new File("extracted");
        String memberName = "path/to/member/file.txt";
        try {
            extractMember(archiveFile, destination, memberName);
            System.out.println("Member extracted successfully.");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
