import java.io.File;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    public static String extractMember(ZipInputStream zipIn, String memberName) throws IOException {
        // Vérifier si le membre commence par un slash
        if (memberName.startsWith("/")) {
            throw new IllegalArgumentException("Les nom de membres ne doivent pas commencer par /.");
        }

        ZipEntry entry = zipIn.getNextEntry();
        while (entry != null) {
            if (entry.getName().equals(memberName)) {
                return readEntry(zipIn);
            }
            zipIn.closeEntry();
            entry = zipIn.getNextEntry();
        }

        throw new IllegalArgumentException("Le membre spécifié n'existe pas dans l'archive.");
    }

    private static String readEntry(ZipInputStream zipIn) throws IOException {
        StringBuilder contentBuilder = new StringBuilder();
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = zipIn.read(buffer)) != -1) {
            contentBuilder.append(new String(buffer, 0, bytesRead));
        }
        return contentBuilder.toString();
    }
}
