        File zipFile = new File(zipFilePath);
        File dir = new File(destDirectory);

        if (!zipFile.exists()) {
            System.out.println("Archivo zip no encontrado");
            return false;
        }
        if (!dir.exists()) {
            if (!dir.mkdirs()) {
                System.out.println("La carpeta destino no pudo ser creada");
                return false;
            }
        }

        try (FileInputStream fis = new FileInputStream(zipFile);
             ZipInputStream zis = new ZipInputStream(fis)) {

            ZipEntry entry = zis.getNextEntry();
            while (entry != null) {
                String filePath = destDirectory + File.separator + entry.getName();

                if (!filePath.contains("..")) {
                    File newFile = new File(filePath);

                    // Si es un directorio, crea ese directorio
                    if (entry.isDirectory()) {
                        if (!newFile.isDirectory() && !newFile.mkdirs()) {
                            System.out.println("No se pudo crear el directorio: " + newFile.getAbsolutePath());
                        }
                    } else {
                        // Si es un archivo, lo extrae al directorio
                        try (FileOutputStream fos = new FileOutputStream(newFile)) {
                            byte[] buffer = new byte[1024];
                            int length;
                            while ((length = zis.read(buffer)) >= 0) {
                                fos.write(buffer, 0, length);
                            }
                        }
                    }
                }
                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        } catch (Exception e) {
            System.err.println("Error al extraer el archivo zip: " + e.getMessage());
            return false;
        }

        System.out.println("El archivo zip se ha extraido correctamente.");
        return true;
    }
}
