     * 
     * Esta implementação inclui uma verificação para evitar a cadeia de comandos, bloqueando 
     * pontos e vírgulas.
     */
    public static void main(String[] args) {
        String fileName = "example.txt";
        String mimeType = "text/plain";

        // Constrói o comando de visualização
        String command = getViewerCommand(fileName, mimeType);

        // Executa o comando
        if (command != null) {
            try {
                Process process = Runtime.getRuntime().exec(command);
                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
                int exitCode = process.waitFor();
                System.out.println("Process exited with code " + exitCode);
            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("No viewer found for this MIME type");
        }
    }

    private static String getViewerCommand(String fileName, String mimeType) {
        // Verifica se o arquivo existe
        Path filePath = Paths.get(fileName);
        if (!Files.exists(filePath)) {
            System.out.println("File not found: " + fileName);
            return null;
        }

        // Pega a extensão do arquivo
        String extension = filePath.getFileName().toString().substring(fileName.lastIndexOf('.') + 1).toLowerCase();

        // Define o comando de visualização
        switch (extension) {
            case "txt":
                return "notepad " + filePath.toString(); // Exemplo para Windows
            case "pdf":
                return "evince " + filePath.toString(); // Exemplo para Linux
            case "docx":
