public class ClassX {
    public static void main(String[] args) {
        // Exemplo de uso do método
        String mimeType = "text/plain";
        String filePath = "/path/to/your/file.txt";
        executeCommand(mimeType, filePath);
    }

    public static void executeCommand(String mimeType, String filePath) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in))) {
            String command = buildCommand(mimeType, filePath);
            System.out.println("Executing: " + command);
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            String s;
            while ((s = stdInput.readLine()) != null) {
                System.out.println(s);
            }
            while ((s = stdError.readLine()) != null) {
                System.err.println(s);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String buildCommand(String mimeType, String filePath) {
        // Verificar a segurança contra pontos e vírgulas
        String secureFilePath = sanitizePath(filePath).replace(";", "%3B").replace(",", "%2C");
        // Construção do comando usando mailcap
        return "mailcap.findmatch -c \"\" -m \"" + mimeType + "\" | awk '{print $1}' | xargs " + secureFilePath;
    }

    private static String sanitizePath(String path) {
        // Implementar a lógica de sanidade de caminho aqui
        // Por exemplo, substituir caracteres especiais por seus equivalentes seguros
        return path.replaceAll("[^a-zA-Z0-9_.-]", "_");
    }
}
