public class ClassX {
    public static void main(String[] args) {
        if (args.length != 2) {
            System.out.println("Usage: java ClassX <mime_type> <file_path>");
            return;
        }

        String mimeType = args[0];
        String filePath = args[1];

        // Regular expression to split the command into parts
        Pattern pattern = Pattern.compile("([a-zA-Z0-9_-]+)(\\s+([a-zA-Z0-9_-]+))?");
        Matcher matcher = pattern.matcher(mimeType);

        StringBuilder commandBuilder = new StringBuilder();
        boolean firstElement = true;

        while (matcher.find()) {
            String element = matcher.group(1);
            String additionalArgument = matcher.group(3);

            if (!firstElement && additionalArgument == null) {
                break; // Stop splitting if we encounter a second element without a following argument
            }

            if (!firstElement) {
                commandBuilder.append(" ");
            }

            commandBuilder.append(element);

            if (additionalArgument != null) {
                commandBuilder.append(" ").append(additionalArgument);
            }

            firstElement = false;
        }

        // Add the file path as the last argument
        commandBuilder.append(" ").append(filePath);

        // Execute the command
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec(commandBuilder.toString()).getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
