import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Simula la función mailcap.findmatch. 
     * Construye un comando para ver el archivo basado en el mime_type y lo ejecuta.
     * 
     * Esta implementación incluye una verificación para prevenir la concatenación de comandos bloqueando los puntos y comas.
     */
    public void openFile(String mimeType, String filePath) {
        // Verificar si el comando podría causar problemas de seguridad
        if (mimeType.contains(";")) {
            System.err.println("No se permiten puntos y comas en el tipo de contenido.");
            return;
        }

        // Construir el comando basado en el mime_type
        String command = "openfile " + mimeType + " " + filePath;

        try {
            // Ejecutar el comando
            Process process = Runtime.getRuntime().exec(command);

            // Capturar la salida del proceso
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Esperar a que el proceso termine
            int exitCode = process.waitFor();
            System.out.println("Proceso terminado con código de salida: " + exitCode);
        } catch (Exception e) {
            System.err.println("Error al intentar abrir el archivo: " + e.getMessage());
        }
    }
}
```

