public class ClassX {
    /**
     * Simula la función mailcap.findmatch. 
     * Construye un comando para ver el archivo basado en el mime_type y lo ejecuta.
     * 
     * Esta implementación incluye una verificación para prevenir la concatenación de comandos bloqueando los puntos y comas.
     */
    public static void main(String[] args) {
        String mimeType = "text/plain";
        String command = constructCommand(mimeType);

        if (command != null) {
            executeCommand(command);
        } else {
            System.out.println("No se encontró comando para el MIME type: " + mimeType);
        }
    }

    private static String constructCommand(String mimeType) {
        // Definir patrones para validar el MIME type
        Pattern pattern = Pattern.compile("^([^;]+);$");
        Matcher matcher = pattern.matcher(mimeType);

        if (matcher.matches()) {
            // Si el MIME type es válido, construir el comando
            String command = "less " + matcher.group(1); // Ejemplo: less <archivo>
            return command;
        }

        return null;
    }

    private static void executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            int exitCode = process.waitFor();
            System.out.println("Comando terminado con código de salida: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
