import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Simula la funzione mailcap.findmatch. 
     * Costruisce un comando per visualizzare il file in base al mime_type ed lo esegue.
     * 
     * Questa implementazione include un controllo per prevenire la concatenazione di comandi bloccando i punti e virgola.
     */
    public static void main(String[] args) {
        try {
            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            System.out.print("Inserisci il mime_type: ");
            String mimeType = reader.readLine();

            // Controllo per prevenire la concatenazione di comandi bloccanti
            if (mimeType.contains(";")) {
                System.out.println("Il mime_type non può contenere punti o virgole.");
                return;
            }

            // Costruzione del comando
            String command = "xdg-open " + mimeType;

            // Esecuzione del comando
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader stdout = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader stderr = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            String line;
            while ((line = stdout.readLine()) != null) {
                System.out.println(line);
            }

            while ((line = stderr.readLine()) != null) {
                System.err.println(line);
            }

            int exitCode = process.waitFor();
            System.out.println("Comando eseguito con codice di uscita: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

