public class ClassX {
    public static void main(String[] args) throws Exception {
        String mimeType = "application/pdf"; // Example MIME type
        String fileName = "document.pdf";

        // Construct the command to view the file based on its MIME type
        String command = constructViewCommand(mimeType, fileName);

        // Execute the command
        executeCommand(command);
    }

    private static String constructViewCommand(String mimeType, String fileName) {
        String[] validCommands = {
            "xdg-open",
            "evince",
            "acroread",
            "google-chrome", // For viewing PDFs in Chrome
            "firefox"       // For viewing PDFs in Firefox
        };

        for (String cmd : validCommands) {
            String command = cmd + " \"" + fileName + "\"";
            if (!isCommandBlocked(command)) {
                return command;
            }
        }

        throw new IllegalArgumentException("No suitable viewer found for MIME type: " + mimeType);
    }

    private static boolean isCommandBlocked(String command) {
        // This is a simple check to prevent command injection by blocking certain characters
        if (command.contains(";") || command.contains("\"") || command.contains("\'")) {
            return true;
        }
        return false;
    }

    private static void executeCommand(String command) {
        Runtime runtime = Runtime.getRuntime();
        Process process = runtime.exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;

        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }

        int exitCode = process.waitFor();
        System.out.println("Command exited with code: " + exitCode);
    }
}
