            System.out.println(line);
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new Exception("Failed to display file: " + exitCode);
        }
    }

    public static void main(String[] args) {
        try {
            displayFile("example.txt", "text/plain; charset=UTF-8");
        } catch (Exception e) {
            e.printStackTrace();
