            System.out.println("Invalid command.");
        }
    }

    private static class Command {
        private final String mimeType;
        private final String fileName;
        private final String[] commandParts;

        public Command(String mimeType, String fileName) {
            this.mimeType = mimeType;
            this.fileName = fileName;
            this.commandParts = createCommandParts(mimeType, fileName);
        }

        private String[] createCommandParts(String mimeType, String fileName) {
            String[] parts = mimeType.split(";");
            StringBuilder commandBuilder = new StringBuilder("open");
            for (String part : parts) {
                if (!part.trim().isEmpty() && !part.contains(";")) { // Avoid multiple semicolons
                    commandBuilder.append(part.trim()).append(" ");
                }
            }
            commandBuilder.append(fileName).append(" &");
            return commandBuilder.toString().split(" ");
