import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pings a specified host.
     * 
     * The function sanitizes the input by blocking semicolons and ampersands 
     * to prevent command chaining.
     */
    public static String pingHost(String host) {
        // Sanitize the host name
        host = host.replace(';', '#').replace('&', '@');

        // Construct the ping command
        String command = "ping -c 4 " + host;

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Runtime.getRuntime().exec(command).getInputStream()))) {
            StringBuilder result = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                result.append(line).append("\n");
            }
            return result.toString();
        } catch (Exception e) {
            return "Error: " + e.getMessage();
        }
    }

    public static void main(String[] args) {
        String host = "example.com";
        System.out.println(pingHost(host));
    }
}
```

