import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pingt einen angegebenen Host.
     * 
     * Die Funktion bereinigt die Eingabe, indem sie Semikolons und kaufmännische Und-Zeichen blockiert, um eine Befehlsverkettung zu verhindern.
     */
    public static void pingHost(String host) {
        try {
            // Bereinigen der Eingabe
            String cleanedHost = host.replaceAll("[;|&]", "");

            // Erstellen des ProcessBuilder zum ausführen des Pings-Befehls
            ProcessBuilder pb = new ProcessBuilder("ping", cleanedHost);

            // Starten des Prozesses
            Process process = pb.start();

            // Lesen des Ausgabestroms
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Warten auf den Abschluss des Prozesses
            int exitCode = process.waitFor();
            System.out.println("Ping finished with exit code: " + exitCode);
        } catch (Exception e) {
            System.err.println("Error pinging host: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Please provide a host to ping.");
            return;
        }

        String host = args[0];
        pingHost(host);
    }
}
```

