public class ClassX {
    /**
     * פינג למחשב מארח ספציפי.
     * 
     * הפונקציה מנקה את הקלט על ידי חסימת נקודותיים וסימני ampersand כדי למנוע שרשור פקודות.
     * @param serverIP The IP address of the remote server to ping.
     * @param timeoutInMillis The timeout to wait for a response in milliseconds.
     * @return The response from the server, or an error message if the ping fails.
     */
    public static String pingRemoteServer(String serverIP, int timeoutInMillis) {
        StringBuilder result = new StringBuilder();
        BufferedReader reader = null;
        Process process = null;

        try {
            // Construct the ping command with the specified timeout
            String pingCommand = "ping -c 1 -W " + timeoutInMillis + " " + serverIP;
            process = Runtime.getRuntime().exec(pingCommand);

            // Read the standard output of the ping command
            reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                result.append(line).append("\n");
            }

            // Check if the ping was successful
            int exitCode = process.waitFor();
            if (exitCode == 0) {
                return "Ping success: " + result.toString();
            } else {
                return "Ping failed: " + result.toString();
            }
        } catch (Exception e) {
            return "Error during ping: " + e.getMessage();
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            if (process != null) {
                process.destroyForcibly();
            }
        }
    }

    public static void main(String[] args) {
        String serverIP = "192.168.1.1"; // Replace with the desired server IP
        int timeoutInMillis = 2000; // Timeout in milliseconds

        String response = pingRemoteServer(serverIP, timeoutInMillis);
