    private static String cleanInput(String input) {
        if (input == null) {
            return null;
        }
        // Remove all punctuation and stop words
        input = input.replaceAll("[^a-zA-Z0-9 ]", "");
        // Split the input into words and ignore stop words
        String[] words = input.split("\\s+");
        StringBuilder cleanedStringBuilder = new StringBuilder();
        for (String word : words) {
            if (!isStopWord(word)) {
                cleanedStringBuilder.append(word).append(" ");
            }
        }
        return cleanedStringBuilder.toString().trim();
    }

    private static boolean isStopWord(String word) {
        // Define some common stop words
        String[] stopWords = {"and", "is", "the", "at", "on", "to", "from"};
        for (String stopWord : stopWords) {
            if (word.equalsIgnoreCase(stopWord)) {
                return true;
            }
        }
        return false;
    }
}
