        StringBuilder sanitizedInput = new StringBuilder();

        // boolean flag to indicate if we are inside a Jinja2 variable
        boolean insideJinja = false;

        while (matcher.find()) {
            if (!insideJinja) {
                // If not inside a Jinja2 variable, append the non-Jinja2 part
                sanitizedInput.append(userInput.substring(0, matcher.start()));
            }
            // Append the current Jinja2 variable (without the delimiters)
            sanitizedInput.append(matcher.group(1));
            // Set the flag to indicate that we are inside a Jinja2 variable
            insideJinja = true;
            // Move past the matched part
            userInput = userInput.substring(matcher.end());
        }

        // Append any remaining non-Jinja2 text
        if (!insideJinja) {
            sanitizedInput.append(userInput);
        }

        return sanitizedInput.toString();
    }

