    /**
     * Рендерира шаблон, включващ потребителски вход.
     * 
     * Функцията се опитва да почисти входа, като блокира делимитрите на променливите на Jinja2.
     *
     * @param input Потребителски вход за рендериране
     * @return Върнат рендерен шаблон
     */
    public String renderTemplate(String input) {
        // Създаване на регулярно израз за блокване на делимитрите на променливите в Jinja2
        Pattern variableDelimiters = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Продължителен цикъл, докато се търсят и блокират делимитрите
        StringBuilder renderedTemplate = new StringBuilder();
        int start = 0;
        while (start < input.length()) {
            Matcher matcher = variableDelimiters.matcher(input.substring(start));
            if (matcher.find()) {
                // Добавяне на съдържанието до първия блокирания делимитър
                renderedTemplate.append(input, start, matcher.start());

                // Добавяне на блокираният делимитър
                renderedTemplate.append("{{").append(matcher.group(1)).append("}}");

