     */
    public void renderTemplate(String templateName, String userInput) {
        // Инициализиране на VelocityEngine
        VelocityEngine ve = new VelocityEngine();
        ve.init();

        // Извличане на шаблон
        Template t = ve.getTemplate(templateName);

        // Създаване на контекст
        VelocityContext context = new VelocityContext();

        // Проверка и блокировка делимитрите на променливите
        userInput = userInput.replaceAll("\\{", "{{").replaceAll("\\}", "}}");

        // Подаване на подходящите данни в контекста
        context.put("userInput", userInput);

        // Временен файл за хранение на резултата
        java.io.File tempFile = new java.io.File("temp.html");
        java.io.Writer writer = new java.io.FileWriter(tempFile);

        // Рендериране на шаблона и записване в временен файл
        t.merge(context, writer);
        writer.close();

        // Представяне или обработка на резултата
