public class ClassX {
    public static String renderInput(String userInput) {
        // Define a regex pattern for Jinja2 variable delimiters (e.g., {{var}})
        Pattern pattern = Pattern.compile("{{(.*?)}}");
        Matcher matcher = pattern.matcher(userInput);

        // StringBuilder to build the cleaned input
        StringBuilder cleanedInput = new StringBuilder();

        // Flag to indicate if the previous character was a space
        boolean wasSpace = false;

        while (matcher.find()) {
            // Get the matched variable name
            String variableName = matcher.group(1);

            // Check if the variable name is not empty and add a space after it
            if (!variableName.isEmpty() && !wasSpace) {
                cleanedInput.append(" ");
            }

            // Append the variable name to the cleaned input
            cleanedInput.append(variableName);

            // Mark the previous character as a space
            wasSpace = true;
        }

        // Append any remaining characters, including spaces
        cleanedInput.append(matcher.replaceFirst(""));

        return cleanedInput.toString();
    }
}
