import org.apache.velocity.Template;
import org.apache.velocity.VelocityContext;
import org.apache.velocity.app.VelocityEngine;
import org.apache.velocity.exception.ParseErrorException;
import org.apache.velocity.exception.ResourceNotFoundException;

public class ClassX {

    /**
     * Kullanıcı girdisini içeren bir şablonu render eder.
     * 
     * Fonksiyon, Jinja2 değişken sınırlayıcılarını engelleyerek girişi temizlemeye çalışır.
     */
    public void renderTemplate(String input) {
        // Initialize VelocityEngine
        VelocityEngine ve = new VelocityEngine();
        ve.init();

        // Create a Template object
        Template template = ve.getTemplate("template.vm");

        // Prepare the context
        VelocityContext context = new VelocityContext();
        context.put("input", input);

        // Render the template with custom filtering
        String filteredInput = filterInput(input);
        context.put("filteredInput", filteredInput);

        try {
            // Process the template
            StringWriter writer = new StringWriter();
            template.merge(context, writer);
            String renderedOutput = writer.toString();

            // Print or use the rendered output
            System.out.println(renderedOutput);
        } catch (ResourceNotFoundException | ParseErrorException e) {
            e.printStackTrace();
        }
    }

    /**
     * Girişi temizleme işlemi.
     */
    private String filterInput(String input) {
        StringBuilder cleanedInput = new StringBuilder();
        for (char c : input.toCharArray()) {
            if (!isJinja2ControlCharacter(c)) {
                cleanedInput.append(c);
            }
        }
        return cleanedInput.toString();
    }

    /**
     * Belirli bir karakter Jinja2 kontrol karakteri mi?
     */
    private boolean isJinja2ControlCharacter(char c) {
        // Custom logic to detect Jinja2 control characters
        // For example: '{', '}', '{{', '}}', etc.
        return (c == '{' || c == '}' || c == '{%' || c == '%}');
    }

    public static void main(String[] args) {
