     * Fungsi ini berusaha untuk membersihkan input dengan memblokir pembatas variabel Jinja2.
     */
    public static String sanitizeInput(String userInput) {
        // Pattern untuk menemukan pembatas variabel Jinja2
        Pattern jinjaVariablePattern = Pattern.compile("\\{\\{(.*?)\\}}");

        // Matcher untuk menemukan kemunculan pembatas variabel Jinja2 dalam input
        Matcher matcher = jinjaVariablePattern.matcher(userInput);

        // StringBuilder untuk menyimpan hasil yang telah disihir
        StringBuilder sanitizedInput = new StringBuilder();

