    public static String renderTemplate(String template, Map<String, Object> data) {
        // Compile a regex pattern to match Jinja2 variables in the template
        Pattern varPattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Iterate over the map of data to replace placeholders with actual values
        for (Map.Entry<String, Object> entry : data.entrySet()) {
            String key = entry.getKey();
