     */
    public String renderTemplateWithInput(HttpServletRequest request) {
        // Eingabe von dem Anfrageparameter "input" extrahieren
        String userInput = request.getParameter("input");

        if (userInput == null) {
            return "No input provided.";
        }

        // Regex für Jinja2-Variablenbegrenzer blockieren
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");
        Matcher matcher = pattern.matcher(userInput);

        // Eingabe bereinigen
        StringBuilder cleanedInput = new StringBuilder();
        while (matcher.find()) {
            cleanedInput.append(matcher.group(0).replace("{", "{{").replace("}", "}}"));
        }
        cleanedInput.append(userInput.replaceAll(pattern, ""));

        return cleanedInput.toString();
    }
}
