import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {

    /**
     * Sanitizes the input by removing Jinja2 template delimiters.
     * 
     * @param input The input string to be sanitized.
     * @return A sanitized string with Jinja2 delimiters removed.
     */
    public static String sanitizeInput(String input) {
        // Regular expression to match Jinja2 template delimiters
        String patternStr = "\\{\\{[^{}]*\\}\\}";
        Pattern pattern = Pattern.compile(patternStr);
        Matcher matcher = pattern.matcher(input);

        // Replace matched patterns with an empty string
        return matcher.replaceAll("");
    }

    public static void main(String[] args) {
        String userInput = "{{ name }} is {{ age }} years old.";
        String sanitizedInput = sanitizeInput(userInput);
        System.out.println("Sanitized Input: " + sanitizedInput);
    }
}
```

