     * @return Il risultato dell'espressione come un double, o null se l'espressione è invalida o contiene parole chiave pericolose.
     */
    public static Double evaluateExpression(String expression) {
        try {
            // Blocco parole chiave potenzialmente pericolose
            String safeExpression = expression.replaceAll("\\bwhile\\b", "")
                                            .replaceAll("\\bfuntion\\b", "")
                                            .replaceAll("\\bif\\b", "")
                                            .replaceAll("\\bdelete\\b", "")
                                            .replaceAll("\\bwith\\b", "")
                                            .replaceAll("\\breturn\\b", "")
                                            .replaceAll("\\bswitch\\b", "")
                                            .replaceAll("\\bthrow\\b", "")
                                            .replaceAll("\\bvar\\b", "")
                                            .replaceAll("\\bfunction\\b", "");

            // Valuta l'espressione
            return (Double) engine.eval(safeExpression);
        } catch (ScriptException e) {
            System.out.println("Errore nella valutazione dell'espressione: " + e.getMessage());
            return null;
        }
    }

    public static void main(String[] args) {
        String userInput = "2 + 3 * 4"; // Esempio di input
        Double result = evaluateExpression(userInput);
        if (result != null) {
            System.out.println("Il risultato è: " + result);
        }
    }
}
