        String[] keywords = {";", "&&", "||", "!", "+", "-", "*", "/", "=", "%", "^", "++", "--"};

        // 检查表达式中是否包含任何禁止的关键词
        for (String keyword : keywords) {
            if (expression.contains(keyword)) {
                System.out.println("Error: Expression contains an illegal keyword.");
