public class ClassX {
    public static void parseAndEvaluateExpression(String expression) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Define a set of disallowed keywords
        String[] disallowedKeywords = {"eval", "setTimeout", "setInterval", "new", "delete", "with", "try", "catch", "finally", "throw", "instanceof", "arguments"};

        // Create a modified expression that excludes disallowed keywords
        StringBuilder modifiedExpression = new StringBuilder();
        for (char c : expression.toCharArray()) {
            if (!isDisallowedKeyword(c)) {
                modifiedExpression.append(c);
            }
        }

        try {
            // Evaluate the modified expression
            Object result = engine.eval(modifiedExpression.toString());
            System.out.println("Result: " + result);
        } catch (Exception e) {
            System.err.println("Error evaluating expression: " + e.getMessage());
        }
    }

    private static boolean isDisallowedKeyword(char c) {
        for (String keyword : disallowedKeywords) {
            if (keyword.length() == 1 && c == keyword.charAt(0)) {
                return true;
            }
        }
        return false;
    }
}
