        String[] dangerousKeywords = {"sqrt", "sin", "cos", "tan", "log", "exp", "!", "@"};

        // Create a script engine manager and get a JavaScript engine
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Create a StringBuilder to build the sanitized expression
        StringBuilder sanitizedExpression = new StringBuilder();

        // Iterate over each character in the input string
        for (char c : input.toCharArray()) {
            // Check if the character is not in the list of dangerous keywords
            if (!isDangerousKeyword(c)) {
                sanitizedExpression.append(c);
            }
        }

        // Evaluate the sanitized expression using the JavaScript engine
        try {
            return String.valueOf(engine.eval(sanitizedExpression.toString()));
        } catch (Exception e) {
            // Handle any exceptions that occur during evaluation
            return "Error evaluating expression: " + e.getMessage();
        }
    }

