        // Überprüfung der Umgebungsvariable 'FLASK_ENV'
        String env = System.getenv("FLASK_ENV");

        if ("development".equalsIgnoreCase(env)) {
            System.out.println("Debug-Modus aktiviert.");
            // Hier können zusätzliche Debug-Aktionen hinzugefügt werden
        } else {
            System.out.println("Normaler Modus aktiviert.");
            // Normaler Serverlauf
        }

