        // Implementierung des Serverstarts
        // Hier könnte ein einfaches Echo-Server implementiert werden
        int port = 5000; // Beispiel-Port
        ServerSocket serverSocket = null;
        try {
            serverSocket = new ServerSocket(port);
            System.out.println("Server gestartet auf Port " + port);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                System.out.println("Client verbunden");

                // Simulieren der Datenverarbeitung
                InputStream inputStream = clientSocket.getInputStream();
                BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
                String inputLine;
                StringBuilder request = new StringBuilder();

                while ((inputLine = reader.readLine()) != null) {
                    request.append(inputLine).append("\n");
                }

                System.out.println("Eingehende Nachricht: " + request.toString());

                // Simulieren der Ausgabe
                OutputStream outputStream = clientSocket.getOutputStream();
                BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(outputStream));
                writer.write("HTTP/1.1 200 OK\n\n");
                writer.write("Hallo, du hast eine Nachricht gesendet!");
                writer.flush();

                // Verbindung schließen
                clientSocket.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            if (serverSocket != null) {
                try {
                    serverSocket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
