import java.security.cert.X509Certificate;

public class ClassX {
    /**
     * Creates an SSL context for connecting to the specified URL.
     * 
     * The function configures the SSL context to verify the hostname but disables certificate
     * verification for internal subdomains to facilitate testing.
     */
    public static SSLContext createCustomSSLContext(String host) throws Exception {
        // Create a trust manager that does not validate certificate chains
        TrustManager[] trustAllCerts = new TrustManager[]{new X509TrustManager() {
            public void checkClientTrusted(X509Certificate[] chain, String authType) {
                // Do nothing if client is trusted
            }

            public void checkServerTrusted(X509Certificate[] chain, String authType) {
                if (chain.length > 0 && checkHostname(host, chain[0].getSubjectDN())) {
                    System.out.println("Hostname verified: " + host);
                } else {
                    System.out.println("Hostname verification failed: " + host);
                }
            }

            private boolean checkHostname(String host, String subjectDN) {
                // Simple hostname check
                return subjectDN.startsWith(host.substring(0, host.indexOf('/')));
            }

            public X509Certificate[] getAcceptedIssuers() {
                return new X509Certificate[0];
            }
        }};

        // Install the all-trusting trust manager
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
        return sslContext;
    }
}
