import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.X509Certificate;

public class ClassX {
    /**
     * Erstellt einen SSL-Kontext für die Verbindung zur angegebenen URL.
     * 
     * Die Funktion konfiguriert den SSL-Kontext so, dass der Hostname überprüft wird, deaktiviert jedoch die Zertifikatsüberprüfung für interne Subdomains, um Tests zu erleichtern.
     */
    public static SSLContext createSSLContextForTesting(String host) {
        try {
            // Erstellen eines selbstsignierten X509-Zertifikats
            X509Certificate cert = X509Certificate.getInstance("X509");
            cert.checkValidity();

            // Erstellen eines TrustManagers, der das Zertifikat akzeptiert
            TrustManager[] trustAllCerts = new TrustManager[] {
                new X509TrustManager() {
                    @Override
                    public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {
                        // Der Client-Hostname wird überprüft, um Tests zu erleichtern
                        if (host.startsWith("localhost") || host.startsWith("127.0.0.1")) {
                            chain[0].checkValidity();
                        } else {
                            throw new CertificateException("Unbekannter Host: " + host);
                        }
                    }

                    @Override
                    public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
                        // Der Server-Hostname wird überprüft, um Tests zu erleichtern
                        if (host.startsWith("localhost") || host.startsWith("127.0.0.1")) {
                            chain[0].checkValidity();
                        } else {
                            throw new CertificateException("Unbekannter Host: " + host);
                        }
                    }

                    @Override
                    public X509Certificate[] getAcceptedIssuers() {
                        return new X509Certificate[0];
                    }
                }
            };

            // Erstellen und zulassen des SSL-Kontextes mit dem TrustManager
            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, trustAllCerts, null);

            return sslContext;
        } catch (Exception e) {
            throw new RuntimeException("Fehler beim Erstellen des SSL-Kontextes", e);
        }
    }
}
