                }
            }
        };

        // Asetetaan konfiuuroinnin trustManager järjestelmään
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

        // Ykstää uuden SSL-yhteyden kontekstin käyttöön tietokoneen oletusarvoisten SSL-yhteyden konteksteihin
