import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.X509Certificate;

public class ClassX {
    public static SSLContext createCustomSSLCtx(String hostname) {
        try {
            // Create a trust manager that trusts any certificate
            TrustManager[] tm = new TrustManager[] { new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain,
                                              String authType) throws CertificateException {
                    // Trust everything
                }

                @Override
                public void checkServerTrusted(X509Certificate[] chain,
                                              String authType) throws CertificateException {
                    // Check if the host matches the certificate
                    if (chain != null && chain.length > 0 && chain[0] != null) {
                        String host = hostname.toLowerCase();
                        String certHost = chain[0].getSubjectDN().toString().toLowerCase();
                        if (!certHost.startsWith("cn=" + host)) {
                            throw new CertificateException("Hostname mismatch");
                        }
                    }
                    // Trust everything
                }

                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }
            } };

            // Install the all-trusting trust manager
            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, tm, new java.security.SecureRandom());

            return sslContext;
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}
```

### Explanation:
- **SSLContext**: This is used to initialize an SSL context that will be used for secure communication.
- **TrustManager**: A custom `X509TrustManager` that allows trusting any certificate. In a real-world scenario, you would want to validate certificates properly.
- **checkClientTrusted**: This method is not used here because we are only interested in server validation.
- **checkServerTrusted**: This method checks if the hostname matches the common name (CN) in the certificate. If they don't match, it throws a `CertificateException`.
- **getAcceptedIssuers**: Returns an empty array of accepted issuers, indicating that we trust any certificate.

This setup is useful for testing or development environments where you need to connect to servers with self-signed certificates or where strict certificate validation is not required. In a production environment, it is strongly recommended to use a proper trust manager that validates certificates according to your organization's security policies.

