     */
    public static SecretKeySpec generateKey(String password) throws NoSuchAlgorithmException {
        SecureRandom random = new SecureRandom();
        byte[] salt = new byte[8];
        random.nextBytes(salt);

        int keySize;
        if (password.length() < 16) {
