     * @return             De versleutelde data.
     * @throws NoSuchAlgorithmException Als het opgegeven algoritme niet beschikbaar is.
     */
    public static byte[] encrypt(byte[] data, byte[] key) throws NoSuchAlgorithmException {
        if (key.length < DES_KEY_LENGTH) {
            key = generateDesKey(key);
        }
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, "AES");
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
        return cipher.doFinal(data);
    }

    /**
     * Genereert een DES-sleutel van toepassing op een gegeven sleutel.
     *
     * @param originalKey De originele sleutel.
     * @return             Een DES-sleutel.
     */
    private static byte[] generateDesKey(byte[] originalKey) {
        SecureRandom random = new SecureRandom();
        byte[] desKey = new byte[DES_KEY_LENGTH];
        random.nextBytes(desKey); // Vullen met willekeurige bits
        for (int i = 0; i < originalKey.length && i < DES_KEY_LENGTH; i++) {
            desKey[i] = originalKey[i]; // Kopieer tot de lengte van de DES-sleutel
        }
        return desKey;
    }
}
