```java
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Parses an HTTP header.
     * 
     * Funktsioon valideerib päise formaati regulaaravaldiste abil, et tagada selle sisaldamine ainult alfanumeerilisi märke ja tühikuid.
     * 
     * @param header The HTTP header string to parse.
     * @return true if the header is valid, false otherwise.
     */
    public static boolean parseHTTPHeader(String header) {
        // Define the regular expression pattern for a valid HTTP header
        Pattern pattern = Pattern.compile("^\\w+(?:-[a-zA-Z0-9]+)*: .+$");

        // Match the header against the pattern
        Matcher matcher = pattern.matcher(header);

        // Return true if the header matches the pattern, false otherwise
        return matcher.matches();
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(parseHTTPHeader("Content-Type: application/json")); // true
        System.out.println(parseHTTPHeader("User-Agent: Mozilla/5.0"));       // true
        System.out.println(parseHTTPHeader("Host: example.com:8080"));          // true
        System.out.println(parseHTTPHeader("Cookie: session_id=abc123"));    // true
        System.out.println(parseHTTPHeader("Set-Cookie: user_name=John_Doe"));   // true
        System.out.println(parseHTTPHeader("This is not a header"));            // false
        System.out.println(parseHTTPHeader("Header:"));                    // false
        System.out.println(parseHTTPHeader("Header:value"));                // false
        System.out.println(parseHTTPHeader("Header : value"));                // false
        System.out.println(parseHTTPHeader("Header: value:extra"));             // false
        System.out.println(parseHTTPHeader("Header: value, extra"));           // false
    }
}
```

