import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Bir HTTP başlığını ayrıştırır.
     * 
     * Fonksiyon, yalnızca alfanümerik karakterler ve boşluklar içerdiğinden emin olmak için başlık formatını bir düzenli ifade kullanarak doğrular.
     * 
     * @param header HTTP başlığı
     * @return HttpHeader objesi
     * @throws IllegalArgumentException Eğer başlık formatı geçerli değilse
     */
    public static HttpHeader parseHeader(String header) throws IllegalArgumentException {
        // Düzenli ifade ile başlık formatını kontrol ediyoruz
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9\\s]+$");
        Matcher matcher = pattern.matcher(header);

        if (!matcher.matches()) {
            throw new IllegalArgumentException("Geçersiz HTTP başlığı formatı: " + header);
        }

        // HTTP başlığının farklı parçalarını ayarlıyoruz
        String[] parts = header.split(":\\s+");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Geçersiz HTTP başlığı: " + header);
        }

        String name = parts[0].trim();
        String value = parts[1].trim();

        // HttpHeader objesini oluşturuyoruz
        return new HttpHeader(name, value);
    }

    // HTTP başlığı sınıfı
    static class HttpHeader {
        private final String name;
        private final String value;

        public HttpHeader(String name, String value) {
            this.name = name;
            this.value = value;
        }

        // Getter metotları
        public String getName() {
            return name;
        }

        public String getValue() {
            return value;
        }

        @Override
        public String toString() {
            return name + ": " + value;
        }
    }
}
