public class ClassX {
    /**
     * Bir HTTP başlığını ayrıştırır.
     * 
     * Fonksiyon, yalnızca alfanümerik karakterler ve boşluklar içerdiğinden emin olmak için başlık formatını bir düzenli ifade kullanarak doğrular.
     * 
     * @param header HTTP başlığı
     * @return HTTP başlığı bilgileri
     * @throws IllegalArgumentException Eğer başlık formatta yanlış ise
     */
    public static Map<String, String> parseHttpHeader(String header) throws IllegalArgumentException {
        // Kullanıcı tarafından sağlanan HTTP başlığı null olabilir
        if (header == null) {
            throw new IllegalArgumentException("HTTP başlığı boş olamaz");
        }

        // HTTP başlığı normal bir string olarak alınır

