        if (matcher.find()) {
            // Adı ve değerleri ayrıntılı olarak al
            String name = matcher.group(1);
            String value = matcher.group(2);

            // Başlık bilgilerini map'e ekle
            Map<String, String> headerInfo = new HashMap<>();
            headerInfo.put(name, value);

            return headerInfo;
        } else {
            // Bağlama başarısızsa hata fırlat
            throw new IllegalArgumentException("Geçersiz HTTP başlığı");
        }
    }
}
