     * @return true se o token é válido, false caso contrário.
     */
    public static boolean verifyJWT(String token) {
        // Simulando a lista de algoritmos suportados
        Map<String, String> supportedAlgorithms = new HashMap<>();
        supportedAlgorithms.put("HS256", "secretKey");
        supportedAlgorithms.put("'none'", "none");

        // Decodificando o token em três partes: header, payload e signature
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return false;
        }

        String header = parts[0];
        String payload = parts[1];
        String signature = parts[2];

        // Validando o algoritmo da assinatura
        String algorithm = header.split(":")[1].trim();
        if (!supportedAlgorithms.containsKey(algorithm)) {
            return false;
        }

        // Verificando a assinatura com base no algoritmo
        String expectedSignature = getSignature(payload, algorithm, supportedAlgorithms.get(algorithm));
        return expectedSignature.equals(signature);
    }

    private static String getSignature(String payload, String algorithm, String key) {
        switch (algorithm) {
            case "HS256":
                try {
                    byte[] decodedPayload = Base64.getUrlDecoder().decode(payload);
                    return Base64.getUrlEncoder().encodeToString(
                            HmacSHA256(key.getBytes(), decodedPayload));
                } catch (Exception e) {
                    e.printStackTrace();
                    return null;
                }
            case "'none'":
                return "";
            default:
