import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.Base64.Decoder;
import java.util.Base64.Encoder;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class ClassX {
    private static final Map<String, String> supportedAlgorithms = new HashMap<>();
    static {
        supportedAlgorithms.put("HS256", "SHA-256");
        supportedAlgorithms.put("none", ""); // Assuming 'none' doesn't require a digest algorithm
    }

    /**
     * Verifica un token JWT (simulado).
     * 
     * La función decodifica el token y valida la firma contra una lista de algoritmos soportados, incluyendo HS256 y 'none'.
     * 
     * @param token El token JWT a verificar.
     * @return true si el token es válido, false en caso contrario.
     */
    public static boolean verifyToken(String token) {
        if (token == null || token.isEmpty()) {
            return false;
        }

        int splitIndex = token.indexOf(".");
        if (splitIndex == -1) {
            return false;
        }

        String headerPart = token.substring(0, splitIndex);
        String payloadPart = token.substring(splitIndex + 1);

        // Simulate decoding the token
        try {
            String decodedHeaderPart = new String(Base64.getDecoder().decode(headerPart));
            String decodedPayloadPart = new String(Base64.getDecoder().decode(payloadPart));

            String signaturePart = token.split("\\.")[2];
            String expectedSignature = createSignature(decodedHeaderPart, decodedPayloadPart, getSigningAlgorithm(decodedHeaderPart));

            return expectedSignature.equals(signaturePart);
        } catch (Exception e) {
            return false;
        }
    }

    private static String getSigningAlgorithm(String headerStr) {
        String[] parts = headerStr.split(":");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Invalid header format");
        }
        return parts[1].trim();
    }

    private static String createSignature(String headerStr, String payloadStr, String algorithm) throws NoSuchAlgorithmException {
        if ("none".equalsIgnoreCase(algorithm)) {
            return "";
        }

        byte[] headerBytes = headerStr.getBytes();
        byte[] payloadBytes = payloadStr.getBytes();

        MessageDigest digest = MessageDigest.getInstance(supportedAlgorithms.get(algorithm).toLowerCase());
        byte[] hashBytes = digest.digest(headerBytes);
        hashBytes = digest.digest(hashBytes);
        hashBytes = digest.digest(hashBytes);

        Encoder encoder = Base64.getUrlEncoder().withoutPadding();
        return encoder.encodeToString(hashBytes);
    }
}
