import java.util.Map;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class ClassX {
    private static final String SECRET_KEY = "your_secret_key";

    public boolean verifyJWT(String jwt) {
        try {
            // Split the JWT into parts
            String[] parts = jwt.split("\\.");
            if (parts.length != 3) {
                return false; // Invalid JWT format
            }

            // Decode the header and payload from Base64
            String header = new String(Base64.getDecoder().decode(parts[0]));
            String payload = new String(Base64.getDecoder().decode(parts[1]));

            // Extract the algorithm from the header
            Map<String, String> headerMap = parseJson(header);
            String algorithm = headerMap.get("alg");

            // Verify the signature based on the algorithm
            if ("HS256".equals(algorithm)) {
                String signature = parts[2];
                byte[] decodedSignature = Base64.getDecoder().decode(signature);
                hmacSignature(payload.getBytes(), SECRET_KEY, decodedSignature);
            } else if ("none".equals(algorithm)) {
                // No signature verification for 'none' algorithm
            } else {
                return false; // Unknown algorithm
            }

            return true; // Token is valid
        } catch (Exception e) {
            return false; // Exception during token verification
        }
    }

    private Map<String, String> parseJson(String json) {
        Map<String, String> map = new HashMap<>();
        String[] pairs = json.split(",");
        for (String pair : pairs) {
            String[] keyValue = pair.split(":");
            if (keyValue.length == 2) {
                map.put(keyValue[0].trim().replaceAll("\"", ""), keyValue[1].trim().replaceAll("\"", ""));
            }
        }
        return map;
    }

    private void hmacSignature(byte[] data, String key, byte[] expectedSignature) throws NoSuchAlgorithmException, InvalidKeyException {
        Mac mac = Mac.getInstance("HmacSHA256");
        SecretKeySpec secretKey = new SecretKeySpec(key.getBytes(), "HmacSHA256");
        mac.init(secretKey);
        byte[] actualSignature = mac.doFinal(data);
        for (int i = 0; i < expectedSignature.length; i++) {
            if (actualSignature[i] != expectedSignature[i]) {
                throw new IllegalArgumentException("Invalid JWT signature");
            }
        }
    }
}
