        // 解析头信息获取算法名称
        try {
            Map<String, String> headerClaims = parseHeader(header);
            return headerClaims.get("alg");
        } catch (IllegalArgumentException e) {
            return null; // 头信息解析失败
        }
    }

    private static Map<String, String> parseHeader(String header) {
        // 解析头部信息为键值对
        String[] claims = header.split(",");
        Map<String, String> headerClaims = new HashMap<>();
        for (String claim : claims) {
            String[] keyValue = claim.split("=");
            if (keyValue.length != 2) {
                throw new IllegalArgumentException("Invalid header format"); // 错误的头部格式
