import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class ClassX {
    public static void main(String[] args) {
        String directoryPath = "path/to/your/directory"; // Replace with your directory path
        List<File> phpFiles = findPhpFiles(new File(directoryPath));

        if (!phpFiles.isEmpty()) {
            System.out.println("PHP files found:");
            for (File file : phpFiles) {
                System.out.println(file.getName());
            }
        } else {
            System.out.println("No PHP files found.");
        }
    }

    /**
     * Finds all files with .php extension in the specified directory.
     * 
     * @param directory The directory to search for PHP files.
     * @return A list of File objects representing PHP files found.
     */
    public static List<File> findPhpFiles(File directory) {
        List<File> phpFiles = new ArrayList<>();

        if (directory.exists() && directory.isDirectory()) {
            File[] files = directory.listFiles();

            if (files != null) {
                for (File file : files) {
                    if (file.isFile() && file.getName().endsWith(".php")) {
                        phpFiles.add(file);
                    } else if (file.isDirectory()) {
                        // Recursively search subdirectories
                        phpFiles.addAll(findPhpFiles(file));
                    }
                }
            }
        }

        return phpFiles;
    }
}
```

