     */
    public void loadDataFromFile(String fileName) {
        // مساعدة تساعدنا في التحقق من الامتداد
        String allowedExtensions[] = {".txt", ".xml", ".json"};

        // الحصول على اسم الملف الصحيح
        String sanitizedFileName = sanitizeFileName(fileName);

        // محاولة انشاء ملف
        File file = new File(sanitizedFileName);

        if (!file.exists()) {
            System.out.println("File not found: " + fileName);
            return;
        }

        // قراءة المحتوى من الملف
        // (هذا الكود يمكن أن يختلف بناءً على الامتداد)
        try {
            if (allowedExtensions.contains(file.getName().substring(file.getName().lastIndexOf('.')))) {
                System.out.println("Loading data from file: " + sanitizedFileName);
                // هنا يمكنك كتابة الكود الذي سيقوم برفع البيانات
            } else {
                System.out.println("Invalid file type: " + fileName);
            }
        } catch (Exception e) {
            System.err.println("Error loading data from file: " + fileName + ": " + e.getMessage());
        }
    }

    /**
     * تعمية اسم الملف للحفاظ على الأمتداد المسموح به.
     * 
     * @param fileName اسم الملف المطلوب التعميم عليه.
     * @return اسم الملف العادي (بدون الامتداد).
     */
    private String sanitizeFileName(String fileName) {
        for (String suffix : allowedExtensions) {
            if (fileName.endsWith(suffix)) {
                return fileName.substring(0, fileName.lastIndexOf('.'));
            }
        }
        return fileName;
    }
}
