     */
    public static File sanitizeFileName(File file) {
        String fileName = file.getName();

        // Pattern to match '.php'
        Pattern phpPattern = Pattern.compile("\\.php$");

        // Check if the file name contains a '.php' extension
        if (phpPattern.matcher(fileName).find()) {
            // If it does, change the filename by replacing '.php' with '.txt'
            fileName = fileName.replace(".php", ".txt");
        }

        // Create a new File object with the sanitized filename
        return new File(file.getParent(), fileName);
    }

    public static void main(String[] args) {
        File originalFile = new File("example.php");
        File sanitizedFile = sanitizeFileName(originalFile);

        System.out.println("Original file: " + originalFile.getAbsolutePath());
        System.out.println("Sanitized file: " + sanitizedFile.getAbsolutePath());
    }
}
