            throw new FileNotFoundException("Файлът не съществува: " + filePath);
        }

        // Проверка дали файлът е файл и не е директория
        if (!file.isFile()) {
            throw new IllegalArgumentException("Файловата пътния е директория: " + filePath);
        }

        // Проверка дали файлът има разширение '.php'
