import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ClassX {
    /**
     * Yüklenen bir dosyadan veri alır (Simüle Edilmiş).
     * 
     * Fonksiyon, '.php' uzantısına sahip dosyaları engelleyerek dosya adını temizler ve böylece betik çalıştırılmasını önler.
     */
    public String fetchData(String filePath) throws IOException {
        File file = new File(filePath);
        if (file.exists() && !file.isDirectory()) {
            String fileName = file.getName();
            if (!fileName.endsWith(".php")) {
                // Dosya adını temizlemek için gerekli işlemler
                fileName = fileName.replace("script-", "").replace(".php", "");
                Path newFilePath = Paths.get(file.getParent(), fileName + ".txt");
                Files.move(file.toPath(), newFilePath);
                return "Data fetched from " + newFilePath.toString();
            } else {
                throw new IOException("PHP script detected. Aborting.");
            }
        } else {
            throw new IOException("File not found or is a directory.");
        }
    }
}
```

