import java.io.File;
import java.util.Arrays;

public class ClassX {
    /**
     * Yüklenen bir dosyadan veri alır (Simüle Edilmiş).
     * 
     * Fonksiyon, '.php' uzantısına sahip dosyaları engelleyerek dosya adını temizler ve böylece betik çalıştırılmasını önler.
     * 
     * @param filePath Dosyanın tam yolu
     * @return Okunan metin
     * @throws Exception Hata oluşursa
     */
    public String readFile(String filePath) throws Exception {
        File file = new File(filePath);

        // Dosyanın geçerli olup olmadığını kontrol et
        if (!file.exists()) {
            throw new FileNotFoundException("Dosya bulunamadı.");
        }

        // Dosyanın uzantısını kontrol et
        if (filePath.endsWith(".php")) {
            throw new IllegalArgumentException("PHP dosyaları yüklenmemelidir.");
        }

        // Dosyanın içeriğini oku
        try (java.util.Scanner scanner = new java.util.Scanner(file)) {
            String content = "";
            while (scanner.hasNextLine()) {
                content += scanner.nextLine() + "\n";
            }
            return content;
        }
    }

    public static void main(String[] args) {
        // Örnek kullanım
        try {
            ClassX classX = new ClassX();
            String content = classX.readFile("example.txt");
            System.out.println(content);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

