    public static void importData(File uploadFile) throws IOException {
        String fileName = uploadFile.getName();
        if (fileName.endsWith(".php")) {
            throw new IOException("File extension '.php' is not allowed.");
        }

        File sanitizedFileName = new File(uploadFile.getParent(), "sanitized_" + fileName);
        try (FileWriter writer = new FileWriter(sanitizedFileName)) {
            // Simulate data import by simply copying the file content
            byte[] buffer = new byte[1024];
            int bytesRead;
            try (FileInputStream fis = new FileInputStream(uploadFile)) {
                while ((bytesRead = fis.read(buffer)) != -1) {
                    writer.write(buffer, 0, bytesRead);
                }
            }
        }
    }
}
