    public static Object loadConfig(String yamlString) {
        // Create a custom constructor to prevent instantiation of unsafe classes
        Constructor constructor = new Constructor() {
            @Override
            protected Object instantiateClass(Class<?> clazz, Object data) throws InstantiationException, IllegalAccessException {
                if (clazz != Object.class) {
                    throw new InstantiationException("Cannot instantiate unsafe class: " + clazz.getName());
                }
                return super.instantiateClass(clazz, data);
            }
        };

        // Initialize the YAML parser with the custom constructor
        Yaml yaml = new Yaml(constructor);

        // Load the configuration from the YAML string
        return yaml.load(yamlString);
    }

    public static void main(String[] args) {
        // Example usage
        String yamlString = "key: value";
        try {
            Object config = loadConfig(yamlString);
            System.out.println(config);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
