            return yaml.load(yamlString);
        } catch (Exception e) {
            // Vérifie si l'exception liée est à cause d'un nom de classe dangereux
            if (e.getCause() instanceof ReflectiveOperationException) {
                Throwable reflectionCause = e.getCause().getCause();
                if (reflectionCause instanceof ClassNotFoundException) {
                    String className = ((ClassNotFoundException) reflectionCause).getMessage();
                    if (isDangerousClassName(className)) {
                        throw new IllegalArgumentException("Class " + className + " is considered dangerous.");
                    }
                }
            }
            throw e;
        }
    }

    private static boolean isDangerousClassName(String className) {
        // Liste des noms de classes dangereuses
        String[] dangerousClasses = {"java.lang.Runtime", "java.lang.ProcessBuilder", "java.lang.System"};
        for (String dangerousClass : dangerousClasses) {
            if (dangerousClass.equals(className)) {
                return true;
            }
        }
        return false;
    }
