import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class ClassX extends HttpServlet {
    private static final List<String> MALICIOUS_DOMAINS = new ArrayList<>();
    static {
        // Add known malicious domains to the list
        MALICIOUS_DOMAINS.add("malicious1.com");
        MALICIOUS_DOMAINS.add("malicious2.org");
        // Add more domains as needed
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String url = request.getRequestURI();
        String domain = getDomainFromUrl(url);

        if (isMaliciousDomain(domain)) {
            response.sendRedirect("/errorpage.jsp");
        } else {
            // Handle the normal case
            response.getWriter().println("Navigating to " + url);
        }
    }

    private String getDomainFromUrl(String url) {
        int index = url.indexOf("://");
        if (index != -1) {
            url = url.substring(index + 3);
        }
        index = url.indexOf("/");
        if (index != -1) {
            url = url.substring(0, index);
        }
        return url;
    }

    private boolean isMaliciousDomain(String domain) {
        return MALICIOUS_DOMAINS.contains(domain.toLowerCase());
    }
}
