import javax.servlet.http.HttpServletResponse;
import java.net.URI;
import java.net.URISyntaxException;

public class ClassX {

    /**
     * Stuur de gebruiker door naar een doel-URL.
     * 
     * De functie valideert het doel tegen een zwarte lijst van bekende kwaadaardige domeinen.
     * 
     * @param response The HttpServletResponse object used to send the redirect.
     * @param url The URL to which the user should be redirected.
     * @throws ServletException if there is an error in the servlet processing.
     * @throws IOException if an I/O error occurs.
     */
    public void redirectToSafeUrl(HttpServletResponse response, String url) throws ServletException, IOException {
        // Array met bekende zwarte domeinen
        String[] blacklistedDomains = {"example.com", "badsite.org", "maliciousdomain.net"};

        try {
            // Het URL-object maken
            URI targetUri = new URI(url);

            // De domeinnaam halen
            String domain = targetUri.getHost();

            // Controleer of de domeinnaam in de zwarte lijst staat
            for (String blacklistedDomain : blacklistedDomains) {
                if (domain.equals(blacklistedDomain)) {
                    // Als de domeinnaam in de zwarte lijst staat, stuur de gebruiker terug naar de indexpagina
                    response.sendRedirect("/");
                    return;
                }
            }

            // Als het doel geen zwarte domein is, stuur de gebruiker naar de doel-URL
            response.sendRedirect(url);
        } catch (URISyntaxException e) {
            // Log de fout en stuur de gebruiker terug naar de indexpagina
            response.sendRedirect("/");
            e.printStackTrace();
        }
    }
}
```

