import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        // Voeg bekende kwaadaardige domeinen toe aan de zwarte lijst
        BLACKLISTED_DOMAINS.add("maliciouswebsite.com");
        BLACKLISTED_DOMAINS.add("evildomain.org");
    }

    public void redirectToSafeUrl(HttpServletResponse response, String targetUrl) {
        if (isSafeDomain(targetUrl)) {
            try {
                response.sendRedirect(targetUrl);
            } catch (Exception e) {
                // Log of verwerk het exception
            }
        } else {
            // Geef een fout bericht terug of stuur gebruiker naar een veilige URL
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access denied for blacklisted domain.");
        }
    }

    private boolean isSafeDomain(String url) {
        String domainPart = extractDomainFromUrl(url);
        return !BLACKLISTED_DOMAINS.contains(domainPart);
    }

    private String extractDomainFromUrl(String url) {
        if (url == null || url.isEmpty()) {
            return "";
        }
        int index = url.indexOf("/");
        if (index != -1) {
            return url.substring(0, index);
        }
        return url;
    }
}
