        blacklistedDomains.add("malicious.com");
        blacklistedDomains.add("harmful.org");
    }

    public void redirectToSafeDomain(String destinationUrl, HttpServletResponse response) {
        if (!isSafeDomain(destinationUrl)) {
            String safeDomain = "safe.example.com";
            response.setStatus(HttpServletResponse.SC_MOVED_PERMANENTLY);
            response.setHeader("Location", safeDomain);
        } else {
            response.sendRedirect(destinationUrl);
        }
    }

    private boolean isSafeDomain(String url) {
        // Implementeer hier een logische controle of de URL verboden is
        // bijvoorbeeld door het domein te matchen met de blacklist
        return !blacklistedDomains.contains(parseDomain(url));
    }

    private String parseDomain(String url) {
        int index = url.indexOf("//");
        if (index != -1) {
            url = url.substring(index + 2); // Verwijder "http://"
        }
        int endOfDomainIndex = url.indexOf('/');
        return endOfDomainIndex == -1 ? url : url.substring(0, endOfDomainIndex);
    }
}
