    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        BLACKLISTED_DOMAINS.add("malicioussite.com");
        BLACKLISTED_DOMAINS.add("phishing.net");
        // Agrega más dominios a la lista negra en caso necesario
    }

    public void redirectSafeURL(HttpServletResponse response, String targetUrl) {
        if (isValidURL(targetUrl)) {
            try {
                response.sendRedirect(targetUrl);
            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            response.sendError(HttpServletResponse.SC_FORBIDDEN);
        }
    }

    private boolean isValidURL(String url) {
        if (url == null || url.isEmpty()) {
            return false;
        }

        // Verifica que el URL comience con "http://" o "https://"
        if (!url.startsWith("http://") && !url.startsWith("https://")) {
            return false;
        }

        // Extrae el dominio del URL
        int domainStartIndex = url.indexOf("//") + 2;
        int domainEndIndex = url.indexOf('/', domainStartIndex);

        if (domainEndIndex == -1) {
            domainEndIndex = url.length();
        }

        String domain = url.substring(domainStartIndex, domainEndIndex);

        // Comprueba si el dominio está en la lista negra
        return !BLACKLISTED_DOMAINS.contains(domain);
    }
}
