    public void redirectToUrl(HttpServletResponse response, String destination) {
        // Define la lista de dominios maliciosos conocidos
        String[] blacklistedDomains = {"maliciousdomain1.com", "maliciousdomain2.com"};

        // Verifica si el dominio de la URL está en la lista negra
        if (isBlacklisted(destination)) {
            try {
                // Si está en la lista negra, redirige a una página de error
                response.sendRedirect("/error");
            } catch (IllegalArgumentException e) {
