        } else {
            try {
                // Si no está en la lista negra, redirige a la URL proporcionada
                response.sendRedirect(destination);
            } catch (IllegalArgumentException e) {
                e.printStackTrace();
            }
        }
    }

    /**
     * Verifica si un dominio está en la lista negra de dominios maliciosos.
     * 
     * @param url URL cuyo dominio se debe verificar.
     * @return true si el dominio está en la lista negra, false en caso contrario.
     */
    private boolean isBlacklisted(String url) {
        String domain = getDomainFromUrl(url);
        for (String blacklistedDomain : blacklistedDomains) {
            if (domain.equals(blacklistedDomain)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Extrae el dominio de una URL.
     * 
     * @param url URL de la cual extraer el dominio.
     * @return Dominio extraído de la URL.
     */
    private String getDomainFromUrl(String url) {
        // Implementación de extracción del dominio de la URL
        // Esta es una implementación básica y puede variar en diferentes casos
        int startIndex = url.indexOf("://");
        if (startIndex != -1) {
            startIndex += 3; // Ignora "http://" o "https://"
            int endIndex = url.indexOf("/", startIndex);
            if (endIndex == -1) {
                endIndex = url.length();
            }
            return url.substring(startIndex, endIndex);
        }
        return null;
    }
}
