     */
    public void redirectToSafeURL(HttpServletResponse response, String targetUrl) {
        try {
            URL url = new URL(targetUrl);
            String hostname = url.getHost();
            boolean isSafe = !BLACKLISTED_DOMAINS.contains(hostname);

            if (isSafe) {
                response.sendRedirect(targetUrl);
            } else {
                response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access denied to this domain.");
            }
        } catch (Exception e) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid URL.");
        }
    }
}
