        "http://phishing.net"
    ));

    public void redirectToTargetURL(HttpServletResponse response, String targetUrl) {
        if (isBlockedDomain(targetUrl)) {
            try {
                response.sendRedirect("http://safefallbackurl.com");
            } catch (IOException e) {
                e.printStackTrace();
            }
        } else {
            try {
                response.sendRedirect(targetUrl);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private boolean isBlockedDomain(String url) {
        String domain = extractDomain(url);
        for (String blockedDomain : BLOCKED_DOMAINS) {
            if (domain.endsWith(blockedDomain)) {
                return true;
            }
        }
        return false;
    }

    private String extractDomain(String url) {
        int lastSlashIndex = url.lastIndexOf('/');
        if (lastSlashIndex != -1) {
            return url.substring(0, lastSlashIndex + 1);
        }
        return url;
    }
}
