            try {
                response.sendRedirect(destination);
            } catch (IllegalArgumentException e) {
                System.err.println("Invalid redirect URL: " + e.getMessage());
            }
        } else {
            System.err.println("Redirect to " + destination + " is blocked due to potential security risks.");
        }
    }

    private boolean isDomainBlacklisted(String url) {
        String domain = extractDomain(url);
        return BLACKLISTED_DOMAINS.contains(domain);
    }

    private String extractDomain(String url) {
        int protocolLength = url.startsWith("http") ? 7 : 8; // "http://" or "https://"
        int portStart = url.indexOf(':');
        int portEnd = url.indexOf('/', portStart + 1);
        if (portEnd == -1) {
            portEnd = url.length();
        }
        return url.substring(protocolLength, Math.min(portStart, portEnd));
    }
}
