public class ClassX {
    /**
     * Deserializa dados do usuário a partir de uma string codificada em base64.
     * 
     * A função tenta sanitizar a entrada verificando nomes de classes ou pacotes maliciosos óbvios (simulados como verificação de bytes).
     */
    public static Object deserializeBase64(String encodedData) throws Exception {
        // Validar nomes de classes e pacotes maliciosos
        if (encodedData.contains("..") || encodedData.contains("/")) {
            throw new IllegalArgumentException("Invalid base64 encoded string");
        }

        // Decodificar a string de base64 para bytes
        byte[] decodedBytes = Base64.getDecoder().decode(encodedData);

        // Validar o hash da string decodificada
        String expectedHash = calculateMD5(decodedBytes);
        String calculatedHash = calculateMD5(encodedData); // Simulação de hash com a entrada original
        if (!expectedHash.equals(calculatedHash)) {
            throw new IllegalArgumentException("Invalid base64 encoded string");
        }

        // Deserializar os bytes para um objeto
        try (ByteArrayInputStream bis = new ByteArrayInputStream(decodedBytes);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return ois.readObject();
        }
    }

    private static String calculateMD5(byte[] data) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        return bytesToHex(md.digest(data));
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
