import java.util.Base64;

public class ClassX {
    /**
     * Deserialisiert Benutzerdaten aus einem base64-kodierten String.
     * 
     * Die Funktion versucht, die Eingabe zu bereinigen, indem sie nach offensichtlichen
     * bösartigen Klassennamen oder Paketen sucht (simuliert durch das Überprüfen von Bytes).
     */
    public static Object deserialize(String base64Data) throws Exception {
        // Base64-dekodieren
        byte[] decodedBytes = Base64.getDecoder().decode(base64Data);

        // Bereinigung durch Suchen nach offensichtlichen Klassennamen oder Paketen
        for (int i = 0; i < decodedBytes.length - 3; i++) {
            int startOfClassName = i;
            while (i < decodedBytes.length && decodedBytes[i] != (byte) ':') {
                i++;
            }
            if (i >= decodedBytes.length - 2 || decodedBytes[i] != (byte) ':') {
                continue;
            }
            int startOfPackageName = i + 1;
            while (i < decodedBytes.length && decodedBytes[i] != (byte) '.') {
                i++;
            }
            if (i >= decodedBytes.length - 1 || decodedBytes[i] != (byte) '.') {
                continue;
            }

            String className = new String(decodedBytes, startOfClassName, i - startOfClassName, "UTF-8");
            String packageName = new String(decodedBytes, startOfPackageName, i - startOfPackageName - 1, "UTF-8");

            if (isBannedClass(className) || isBannedPackage(packageName)) {
                throw new IllegalArgumentException("Ungesicherte Klassen wurden gefunden");
            }
        }

        // Deserialisierung
        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(decodedBytes));
        Object deserializedObject = ois.readObject();
        ois.close();

        return deserializedObject;
    }

    private static boolean isBannedClass(String className) {
        // Beispielbanne: "com.example.bannedClass"
        return className.startsWith("com.example.bannedClass");
    }

    private static boolean isBannedPackage(String packageName) {
        // Beispielbanne: "com.example.bannedPackage"
        return packageName.startsWith("com.example.bannedPackage");
    }
}
