        TrustManagerFactory trustAllCerts = TrustManagerFactory.getInstance("SunX509");
        trustAllCerts.init((java.security.KeyStore) null);

        // Install the trust manager in the SSLContext
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts.getTrustManagers(), new java.security.SecureRandom());
