import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;
import java.io.IOException;

public class ClassX {
    /**
     * Analizza un documento XML.
     * 
     * La funzione controlla la presenza di dichiarazioni 'DOCTYPE' per prevenire XXE.
     * 
     * @param xmlContent Il contenuto XML da analizzare
     * @return true se la 'DOCTYPE' è presente, false altrimenti
     */
    public boolean checkDoctype(String xmlContent) {
        try {
            // Crea un factory per creare un builder
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true); // Disabilita la dichiarazione DOCTYPE

            // Imposta l'uso del parser XSD
            factory.setFeature("http://apache.org/xml/features/validation/schema", true);

            // Imposta l'uso del parser XML 1.1
            factory.setFeature("http://apache.org/xml/features/xml11-compatible", true);

            // Imposta l'uso del parser DTD
            factory.setFeature("http://apache.org/xml/features/validation/dtd", true);

            // Imposta l'uso del parser namespaces
            factory.setNamespaceAware(false);

            // Crea un builder
            DocumentBuilder builder = factory.newDocumentBuilder();

            // Converte il contenuto XML in un istanza di Document
            byte[] xmlBytes = xmlContent.getBytes("UTF-8");
            Document document = builder.parse(new ByteArrayInputStream(xmlBytes));

            // Controlla se la 'DOCTYPE' è presente
            return document.getDoctype() != null;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }
}
```

