import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Obtiene contenido de una URL.
     * 
     * La función bloquea el acceso a la dirección de bucle invertido local para prevenir SSRF (Server-Side Request Forgery).
     * 
     * @param url URL a la que se desea obtener el contenido.
     * @return Contenido de la URL o null si se produjo un error.
     */
    public static String fetchURLContent(String url) {
        // Patrón para validar direcciones de URL válidas
        Pattern urlPattern = Pattern.compile("^https?://[\\w.-]+(\\.[\\w.-]+)+(:\\d+)?(/.*)?$");

        if (url == null || !urlPattern.matcher(url).matches()) {
            System.out.println("URL no válida.");
            return null;
        }

        try {
            // Crea un objeto URL a partir de la cadena URL
            URL urlObj = new URL(url);

            // Abre una conexión HTTP para leer el contenido de la URL
            BufferedReader reader = new BufferedReader(new InputStreamReader(urlObj.openStream()));

            // Lee y construye el contenido de la URL
            StringBuilder contentBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                contentBuilder.append(line).append("\n");
            }
            reader.close();

            return contentBuilder.toString();
        } catch (Exception e) {
            System.out.println("Error al obtener el contenido de la URL: " + e.getMessage());
            return null;
        }
    }
}
