import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * Haal inhoud op van een URL.
     * 
     * De functie blokkeert de toegang tot het lokale loopback-adres om SSRF te voorkomen.
     *
     * @param urlString De URL waarvan de inhoud moet worden gehaald.
     * @return De inhoud van de URL als String.
     * @throws Exception Als er een probleem optreedt bij het ophalen van de inhoud.
     */
    public String fetchURLContent(String urlString) throws Exception {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setConnectTimeout(5000); // Timeout in milliseconds
        connection.setRequestMethod("GET");
        connection.setRequestProperty("User-Agent", "Mozilla/5.0"); // Prevents SSRF by setting a user agent

        BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            content.append(line).append("\n");
        }
        reader.close();

        // Check for SSRF prevention by comparing the IP address of the accessed URL to the local loopback address
        if (!url.getHost().equals("127.0.0.1")) {
            throw new Exception("SSRF detected: Accessing external URL!");
        }

        return content.toString();
    }
}
```

