```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * Haal inhoud op van een URL.
     * 
     * De functie blokkeert de toegang tot het lokale loopback-adres om SSRF te voorkomen.
     * 
     * @param urlString Het adres van de URL waarvan de inhoud wordt opgehaald.
     * @return De inhoud van de URL als een String.
     */
    public static String fetchData(String urlString) {
        try {
            // Creëer een URL-object met het opgegeven URL-adres
            URL url = new URL(urlString);

            // Maak een HTTP-verbinding naar de URL
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            // Controleer of de verbinding gelukt is
            if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Failed to connect to " + urlString);
            }

            // Creeër een BufferedReader om de inputstream te lezen
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));

            // Lees de inhoud gelezen uit de BufferedReader
            StringBuilder contentBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                contentBuilder.append(line).append("\n");
            }

            // Sluit de BufferedReader en de HTTP-verbinding
            reader.close();
            connection.disconnect();

            // Geef de inhoud als String terug
            return contentBuilder.toString();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static void main(String[] args) {
        // Voorbeeld van het gebruik van de fetchData-functie
        String urlString = "http://example.com";
        String content = fetchData(urlString);

        if (content != null) {
            System.out.println("Inhoud van de URL:");
            System.out.println(content);
        } else {
            System.out.println("Er is een fout opgetreden bij het ophalen van de inhoud van de URL.");
        }
    }
}
```

