        Pattern pattern = Pattern.compile("http:\\/\\/localhost|http:\\/\\/127\\.0\\.0\\.1");
        Matcher matcher = pattern.matcher(urlString);

        if (matcher.find()) {
            throw new IllegalArgumentException("Access to localhost or 127.0.0.1 is denied.");
        }

        try {
            URL url = new URL(urlString);
            BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append(System.lineSeparator());
            }
            reader.close();
            return content.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error while fetching content from URL: " + urlString, e);
        }
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        try {
            String content = classX.fetchContentFromURL("http://example.com");
            System.out.println(content);
        } catch (IllegalArgumentException | RuntimeException e) {
            System.err.println(e.getMessage());
        }
    }
}
